pub(super) fn entries() -> Vec<KernelRule> {
    vec![
        // -- cross-run-profiles-key-on-content-not-stat-triplets --
        // distilled from the oMLX PR #3260 SSD expert-streaming module
        // (head 3343e44): warm-start hotlist profiles fingerprinted
        // sha256(path + NUL + st_size + NUL + st_mtime_ns), first 24
        // hex chars as the profile filename. Any mtime-preserving copy
        // of a different artifact matches the stale profile; any touch
        // of the same artifact drops a still-valid one. Sibling hazard:
        // _hotlist_identity stats the index unconditionally (no try)
        // beside fully guarded save/load siblings -- latent in the
        // production call order, reachable via TOCTOU or future callers.
        // Anchors: integrate.py:196-200, :191-201, :221.
        // Batch 94 / Research 110 / Plan 058.
        KernelRule {
            rule_id: "cross-run-profiles-key-on-content-not-stat-triplets".to_string(),
            gpu_concept: "A cross-run persisted profile (learned hotlists, caches, tuned configs keyed to an artifact) keyed by file METADATA -- path, size, mtime_ns -- instead of by CONTENT silently answers the wrong question in both directions: an mtime-preserving copy of a DIFFERENT artifact (re-quantized checkpoint, re-sharded export, renamed variant) matches the stale profile and warms the cache with another model's learned state, while a legitimate copy or touch of the SAME artifact invalidates a still-valid profile and silently discards the learning. Key on content: stream-hash the artifact bytes (BLAKE3) or derive identity from the loader's own parsed structure, and treat the derivation as an ASSERTED property -- a fingerprint whose derivation is never validated against the bytes it names is an unverified claim. Guard discipline must be CONSISTENT within a module: the source's save and load paths are fully exception-guarded (degrade to a fresh profile) while the identity derivation above them carries an unconditional stat with no handler -- on a missing index the whole install crashes from the least-defensive line in the file; the crash was latent in the production call order (an earlier index constructor raises a clean error first) but is reachable via TOCTOU or any future direct caller, so write the guard at the derivation, not at one caller. Correctness-axis rule: a stale warm start is not slow, it is WRONG cache state. Measured context: the profiles persist lifetime route-selection counts across runs (the source's cross-run hotlist -- published prior absent per Research 110). Distinct from weight-handle-cache-keyed-by-allocation-identity (pointer identity is the CORRECT key within one process for a live allocation; stat identity is not a content key across runs), from derive-shape-from-payload-not-cached-field (in-memory field drift within one session; this is cross-run artifact identity), from commit-over-maintained-item-digests (digest MAINTENANCE cadence so commitment is O(items) -- composes as the content-hash substrate), and from serialize-container-canonical-order (deterministic serialization of content; this keys BY content). Source: jundot/omlx PR #3260 integrate.py:196-200 (sha256 over path, st_size, st_mtime_ns NUL-joined, first 24 hex chars as the profile filename), :191-201 (unguarded _hotlist_identity beside fully guarded _save_hotlist/_load_hotlist), :221 (load rejects a fingerprint mismatch and falls back to optimistic fill). Batch 94 / Research 110 / Plan 058.".to_string(),
            ref_shape: "// warm-start profile keyed by file stat metadata -- copy-safe, content-blind\nfn profile_key(path: &Path) -> String {\n    let st = fs::metadata(path).unwrap(); // unconditional: crashes if absent\n    // ident = path + SEP + size + SEP + mtime_ns (SEP is a NUL byte in source)\n    let ident = build_stat_ident(path, st.len(), st.mtime_ns());\n    sha256_hex(ident.as_bytes())\n}\n// a byte-identical COPY of the checkpoint gets a fresh key (learning lost);\n// a DIFFERENT checkpoint with preserved size+mtime gets the same key\n// (foreign warm start) -- both wrong, both silent.\n\n".to_string(),
            opt_pattern: "// key on CONTENT: stream-hash the artifact once; derivation guarded like\n// its save/load siblings -- a missing artifact degrades, never crashes\nfn profile_key(path: &Path) -> Option<String> {\n    let file = File::open(path).ok()?;\n    let mut h = blake3::Hasher::new();\n    let mut rd = BufReader::new(file);\n    let mut buf = vec![0u8; 1 << 20];\n    loop {\n        let n = rd.read(&mut buf).ok()?;\n        if n == 0 {\n            break;\n        }\n        h.update(&buf[..n]);\n    }\n    let hex = h.finalize().to_hex().to_string();\n    Some(hex[..24].to_string())\n}\n// copies of the same bytes share the key; different bytes never collide --\n// a re-quant is a different artifact and correctly starts a fresh profile\n\n".to_string(),
        },

        // -- fill-gate-speculation-until-working-set-resident --
        // distilled from execution.py: the readiness latch gates the
        // speculative regime on every pool's cache_full, is checked
        // once and never reset, and counts refused passes. Measured
        // justification (docs/soft_reap.md:142-150): pre-gate
        // speculative 166.965 s vs 14.709 s checked on the same
        // fixture; honest ceiling: at a 100% resident hit rate the
        // speculative graph still measured 0.579 s vs 0.556 s checked.
        // Anchors: execution.py:240-244, :235-237; pool.py:287-290.
        // Batch 94 / Research 110 / Plan 058.
        KernelRule {
            rule_id: "fill-gate-speculation-until-working-set-resident".to_string(),
            gpu_concept: "A speculative-execution regime (draft on resident weights, verify routing, retry on miss) must be ADMITTED only once the resident working set is complete: gate the regime until EVERY layer's evictable cache is at capacity, LATCH the readiness bit once satisfied (steady state then pays zero per-token check), and COUNT the refused passes so the gate's cost is visible in stats. The justification is measured on both sides: before the gate, a partially-filled cache made every speculative pass compute on placeholder weights and end in a rejected whole-model rollback -- 166.965 s speculative vs 14.709 s checked on the same fixture; and the honest ceiling: even at a 100% resident hit rate the speculative graph measured 0.579 s vs 0.556 s checked (4% SLOWER), so speculation only pays when the whole working set is resident AND real hits exist -- at partial fill it buys nothing but rejected passes. Latch SCOPE is a contract: a process-global latch is correct for a single-request decode loop; a multi-request server must scope it per working set, else a fresh request speculates on someone else's warm cache. Related admission discipline: residency estimates must budget runtime growth (KV growth OOMed an estimate that ignored it -- Research 110 section 8). Distinct from predicate-gated-skip-empty-workset-step (skips a step when the work set is EMPTY -- cost elision; this refuses to START a regime until capacity -- admission control, the complement), from hardcoded-fast-path-jit-specialization (eligibility static at dispatch-config time; this is runtime fill state), and from size-gate-covers-every-cost-factor (a cost gate's INPUT completeness; this is a protocol gate on when speculation may begin at all). Source: jundot/omlx PR #3260 execution.py:240-244 (latch: _cache_fill_ready = all(pool.cache_full) once, never reset), :235-237 (fill_gated_passes counter), pool.py:287-290 (cache_full = every evictable slot populated); docs/soft_reap.md:142-150. Batch 94 / Research 110 / Plan 058. RIDER (Batch 113 external instance, ggml-org/llama.cpp @ 5266f24da v0.4.0 -- the sparse-attention hint path (fa.metal:1152-1156) clamps the same way: 'if the hint is violated, keep only the first n_kv_max entries' -- an admission hint that over-promises is CLAMPED to the capacity and attention degrades to prefix-correct, never speculates past the resident set.".to_string(),
            ref_shape: "// speculation admitted immediately; partial cache = placeholder computes\nlet mut out_total = 0u32;\nloop {\n    let draft = speculate(&graph, &banks); // missing experts read slot 0\n    let (missing, out) = verify(&draft);\n    if missing {\n        rollback_cache(); // the whole pass is wasted\n        out_total += checked_step(&graph, &banks); // pay checked anyway\n    } else {\n        out_total += out;\n    }\n    if out_total >= BUDGET {\n        break;\n    }\n}\n\n".to_string(),
            opt_pattern: "// gate: refuse until every layer's evictable cache is at capacity; latch\nstruct SpecGate {\n    ready: bool,\n    gated_passes: u64,\n}\nimpl SpecGate {\n    fn can_speculate(&mut self, pools: &[Pool]) -> bool {\n        if !self.ready {\n            self.ready = pools.iter().all(|p| p.cache_full()); // one scan, latched\n        }\n        if !self.ready {\n            self.gated_passes += 1; // refusals visible in stats\n            return false;\n        }\n        true\n    }\n}\n// steady state: one bool read per token, zero scans; before ready: the\n// checked path (which fills the cache, eventually arming the latch)\n\n".to_string(),
        },

        // -- decayed-frequency-eviction-recency-tiebreak-route-protection --
        // DwarfStar-derived hot-cache policy (docs/soft_reap.md:175-177):
        // hotness halves every 16 routed tokens (saturating u64);
        // victim = min (hotness, last_used) over unprotected candidates;
        // routes noted BEFORE hit/miss classification (misses score);
        // the current route's experts excluded from eviction; fail loud
        // when nothing is evictable. Warm-start hazard (bug yield):
        // lifetime counts seeded raw into the DECAYED field at
        // pool.py:497-499 make warm experts near-immune (~64,000x skew)
        // and split-brain the persisted (undecayed) vs working (decayed)
        // rankings. Anchors: pool.py:194, :428-439, :516-534, :571, :588.
        // Batch 94 / Research 110 / Plan 058.
        KernelRule {
            rule_id: "decayed-frequency-eviction-recency-tiebreak-route-protection".to_string(),
            gpu_concept: "A fixed-capacity resident cache for ROUTED operands (per-layer expert weights, adapters, KV segments) needs an eviction policy shaped by route distribution, not raw access order: (1) exponential DECAY -- halve every hotness score every N routed tokens (saturating integers; N = 16 in the source) so dormant experts age out even if they were hot earlier in the session; (2) recency as TIE-BREAK only -- evict min-hotness, break ties by oldest last-use (plain LRU lets one recency spike evict a repeatedly-routed expert; plain LFU pins stale lifetime favorites forever); (3) score BOTH hits and misses -- note the route BEFORE classifying hit or miss, because a miss is demand signal too: the expert the router keeps asking for is exactly the one worth caching; (4) PROTECT the current route -- experts named by the in-flight route are excluded from victim candidates (they are about to be consumed); (5) FAIL LOUD when no candidate remains -- an all-protected candidate set means the protection set itself is wrong, so raise rather than evict a protected expert. Warm-start interaction (bug yield): seeded lifetime counts must land in a SEPARATE field from the decayed working score -- seeding them into the decayed field makes warm experts eviction-immune for roughly log2(count) x N routed tokens with zero recent use, and creates a split brain where eviction ranks by the decayed field while the persisted hotlist ranks by undecayed lifetime counts (the two orderings disagree after a long session). Bench axis: hot-set retention on synthetic route traces vs LRU and LFU controls. Distinct from layer-depth-decay-schedule (a training-time weight-decay schedule indexed by layer depth; this is runtime cache-hotness decay), from order-stable-topk-via-index-sort (selection ordering for retention lists; this is the victim-choice policy that fills the resident set), and from make-unmake-over-clone-per-candidate (candidate-search state rollback; unrelated to cache victim choice). Source: jundot/omlx PR #3260 pool.py:194 (decay interval 16), :428-439 (note_route: increment + array halving + saturating counters), :516-534 (victim: min of (hotness, last_used) over unprotected candidates, RuntimeError otherwise), :571 (note BEFORE the hit/miss classification), :588 (protected = the current route set), :497-499 (the warm-start seeding hazard), docs/soft_reap.md:175-177 (DwarfStar lineage). Batch 94 / Research 110 / Plan 058.".to_string(),
            ref_shape: "// plain LRU victim over the resident set; misses never score\nfn victim_lru(last_used: &HashMap<Expert, u64>) -> Expert {\n    let mut best: Option<(u64, Expert)> = None;\n    for (e, t) in last_used {\n        match best {\n            Some((bt, _)) if *t >= bt => {}\n            _ => best = Some((*t, *e)),\n        }\n    }\n    best.expect(\"empty cache\").1\n}\n// one recency spike evicts the workhorse; an expert the router demands\n// every step but never finds resident never gains heat at all\n\n".to_string(),
            opt_pattern: "// decayed frequency + recency tie-break + route protection, fail loud\nconst DECAY_INTERVAL: u64 = 16; // routed tokens per halving\nfn note_route(hot: &mut HashMap<Expert, u64>, route: &[Expert],\n              routed_tokens: u64, next_decay: &mut u64) {\n    for e in route {\n        *hot.entry(*e).or_insert(0) += 1; // hits AND misses both score\n    }\n    while routed_tokens >= *next_decay {\n        for v in hot.values_mut() {\n            *v >>= 1; // saturating halving: dormant experts age out\n        }\n        *next_decay += DECAY_INTERVAL;\n    }\n}\nfn victim(hot: &HashMap<Expert, u64>, last_used: &HashMap<Expert, u64>,\n          protected: &HashSet<Expert>) -> (Expert, u64, u64) {\n    let mut best: Option<(u64, u64, Expert)> = None;\n    for (e, h) in hot {\n        if protected.contains(e) {\n            continue; // the current route is untouchable\n        }\n        let u = last_used.get(e).copied().unwrap_or(0);\n        if best.map_or(true, |b| (*h, u) < (b.0, b.1)) {\n            best = Some((*h, u, *e));\n        }\n    }\n    let (h, u, e) = best.expect(\"all candidates protected: wrong protection set\");\n    (e, h, u) // min-hotness primary, oldest-use tie-break\n}\n\n".to_string(),
        },

        // -- defer-promoted-write-to-first-consumer-dispatch --
        // distilled from pool.py:411-413 (in-source: dynamic updates
        // deliberately remain lazy -- the layer's QMM consumes the
        // updated bank immediately and the next layer's router
        // evaluation provides the required synchronization) and
        // :654-658 (promote evaluates only the tiny routing maps:
        // forcing every projection here only materializes the same
        // writes twice). Bind/materialize timing split :391-410;
        // integrate.py:87-88 stats keys. Batch 94 / Research 110 /
        // Plan 058.
        KernelRule {
            rule_id: "defer-promoted-write-to-first-consumer-dispatch".to_string(),
            gpu_concept: "Split a cache promotion into BIND and MATERIALIZE and defer the materialization to the FIRST consumer dispatch: bind now (route-to-slot metadata, index maps -- tiny and needed immediately for correctness), materialize lazily (the bank bytes -- the next dispatch that reads the bank forces them anyway, so the next layer's router evaluation IS the synchronization fence), and do NOT add an explicit eval after every dynamic update: forcing every projection at promote time only materializes the same writes twice. Keep the two phases SEPARATE in the stats (bind seconds vs materialize seconds) so the deferral is measurable rather than invisible. Scope the laziness honestly: warm-start and pinned-preload paths materialize EAGERLY (component-at-a-time to cap transient memory) -- only the dynamic miss/promote path defers. The decision content is not laziness itself (an eager graph framework gives that for free) but the TWO-PHASE SPLIT plus IDENTIFYING the existing implicit fence -- naming which downstream dispatch already orders the writes, so no new barrier is added and none is missing. Distinct from deferred-residual-fused-into-next-layer-norm (defers an ARITHMETIC op into the next layer's FUSED KERNEL -- op-fusion placement; this defers DATA MATERIALIZATION behind an identified implicit fence -- no kernel changes at all), from defer-readback-until-after-submit (host-side readback timing after submit; this is device-side write timing into a consumer dispatch), and from mid-pipeline-device-alloc-is-implicit-sync (an allocation HIDING a sync you must account for; here an existing consumer IS the sync you rely on -- name it). Source: jundot/omlx PR #3260 pool.py:411-413 (in-source comment: dynamic updates deliberately remain lazy -- the layer's QMM consumes the updated bank immediately and the next layer's router evaluation provides the required synchronization), :654-658 (promote evaluates only the tiny routing maps: forcing every projection here only materializes the same writes twice), :391-410 (bind vs materialize timing split at the write site), integrate.py:87-88 (bank_bind_seconds and bank_materialize_seconds as separate stats). Batch 94 / Research 110 / Plan 058.".to_string(),
            ref_shape: "// eager materialization at every dynamic update: writes forced twice\nfn promote(pool: &mut Pool, experts: &[Expert]) {\n    let t0 = Instant::now();\n    bind_slots(pool, experts); // route -> slot metadata\n    write_bank_rows(pool, experts);\n    pool.ctx.eval_all(); // forces EVERY pending write, not just ours\n    pool.stats.materialize_seconds += t0.elapsed().as_secs_f64();\n}\n// the very next layer dispatch reads this bank and would have forced\n// these writes anyway -- the explicit eval is a second full pass\n\n".to_string(),
            opt_pattern: "// bind now; the first consumer dispatch materializes; the fence is named\nfn promote(pool: &mut Pool, experts: &[Expert]) {\n    let t0 = Instant::now();\n    bind_slots(pool, experts); // slot map + resident mask\n    pool.ctx.eval(&pool.slot_map); // tiny maps ARE consumed host-side now\n    pool.stats.bind_seconds += t0.elapsed().as_secs_f64();\n    // bank rows written lazily; FENCE: the next layer's router dispatch on\n    // the same stream orders them before any read (named in the comment)\n}\n// warm-start + pinned preload stay eager (component-at-a-time to cap\n// transient memory); stats keep bind and materialize separate so the\n// split is measurable in every session\n\n".to_string(),
        },

        // -- rollback-snapshot-covers-all-mutable-state --
        // defense rule distilled from execution.py's CacheSnapshot:
        // (a) ndarray-like leaves captured BY REFERENCE -- safe only
        // under the docstring's append-only contract (:44-50), whose
        // boundary in-place mutation breaks; (b) __dict__-less objects
        // silently skipped (:93-95); (c) coverage scoped to the
        // conventionally-named cache argument (:219-222 + :283).
        // First-miss-only trust comment at :277-278; retry x1 +
        // restore + promote + checked fallback at :283-308. Batch 94
        // / Research 110 / Plan 058.
        KernelRule {
            rule_id: "rollback-snapshot-covers-all-mutable-state".to_string(),
            gpu_concept: "A rollback snapshot used by a speculate-verify-retry loop must publish its COVERAGE CONTRACT and be audited against three silent under-coverage modes: (1) MUTABLE-CONTENT LEAVES -- containers whose bytes can mutate (ndarray-like array types) treated as immutable leaves captured BY REFERENCE are safe ONLY under an append-only write contract (the source states it exactly: the caches append by replacing array references or by writing beyond their previous logical offset, and a retry writes the same append region before it can be observed -- an IN-PLACE mutation of already-visible bytes would leak straight through into the retry); (2) STATELESS-LOOKING OBJECTS -- instances without a __dict__ (__slots__ classes, builtins) silently skipped by the capture walk: their state mutations never roll back and nothing records the skip; (3) ARGUMENT-SCOPED COVERAGE -- the snapshot covers exactly the conventionally-named cache argument (a kwarg or one fixed positional); any OTHER state the speculative pass mutates (pool bookkeeping, module counters, sibling fields) is never restored. Each mode is acceptable ONLY as a written contract with the cache implementations; make the contract load-bearing: a registry of cache types with their mutation discipline, a debug-mode tripwire for unregistered mutable state, and the policy that rejected speculative outputs are NEVER returned to the caller (containment by contract, not by faith in the poison). Bounded retry budget (x1), restore before BOTH the promote-retry and the checked fallback, and FIRST-MISS-ONLY TRUST: once a route was computed from placeholder output, downstream routes are not valid analytical signal (the source's own comment says exactly this). Distinct from rotated-ring-undo-via-rebind-reference-snapshot (the UNDO MECHANICS for one rotated-ring cache family -- exploiting a rebind-contract update path; this is the COVERAGE CONTRACT every snapshot implementation must publish and audit), from staged-append-rollback-lifo-retry-blocks (physical block reproduction on retry so captured graphs survive; this is what STATE the snapshot must cover at all), and from write-before-read-state-skips-checkpoint (which state NEEDS NO backup because re-execution repairs it; the boundary of that argument is exactly the append-only contract -- in-place mutation breaks it). Source: jundot/omlx PR #3260 execution.py:44-50 (the append-only contract docstring), :60-66 (leaf set including ndarray, captured by reference), :93-95 (__dict__-less objects silently skipped), :219-222 + :283 (snapshot scoped to the cache argument), :277-278 (first-miss-only trust comment), :283-308 (restore, promote first missing layer, retry x1, checked fallback, rejected passes never returned). Batch 94 / Research 110 / Plan 058.".to_string(),
            ref_shape: "// snapshot trusts the walk and the scope; every gap is silent\nstruct Snapshot {\n    saved: Vec<u8>,\n}\nfn speculative_pass(model: &Model, cache: &mut Cache, stats: &mut Stats) -> Vec<u8> {\n    let snap = Snapshot { saved: cache.clone_bytes() }; // cache arg only\n    let out = model.forward_speculative(cache);\n    if missing_experts(&out) {\n        cache.restore_bytes(&snap.saved); // cache rolled back\n        // stats mutated by the pass: NOT rolled back (out of scope)\n        // a __slots__ cache node: never captured, nothing noted\n        return model.forward_checked(cache);\n    }\n    out // a careless caller can return the rejected (poisoned) pass\n}\n\n".to_string(),
            opt_pattern: "// coverage contract explicit; unregistered mutable state trips in debug\ntrait RollbackState {\n    fn capture(&self) -> Box<dyn RollbackState>;\n    fn restore(&mut self, snap: &dyn RollbackState);\n    fn discipline(&self) -> Discipline; // AppendOnly | FullyCloned\n}\nfn speculative_pass(model: &Model, cache: &mut Cache, stats: &mut Stats) -> Vec<u8> {\n    debug_assert_registered(cache.type_id()); // tripwire: unregistered type\n    let snap = cache.capture(); // cache AND registered satellites\n    let stats0 = stats.checkpoint(); // every mutated state covered\n    let out = model.forward_speculative(cache);\n    if missing_experts(&out) {\n        cache.restore(snap.as_ref());\n        stats.restore(&stats0);\n        return model.forward_checked(cache); // rejected output NEVER returned\n    }\n    out\n}\n// Discipline::AppendOnly leaves are legal ONLY with the append contract\n// written beside the cache implementation (a retry rewrites its own region)\n\n".to_string(),
        },

        // -- scratch-bank-isolates-one-shot-operands-from-hot-cache --
        // distilled from pool.py: the ANTI-SHAPE _forward_expert_major
        // (:837-894) chunks cold groups through the dynamic banks
        // (:852-858) with the evict-then-evaluate comment at :891;
        // the FIX _forward_expert_major_scratch (:896-1011) executes
        // one-shot cold experts in a reserved scratch region
        // (docstring :902; scratch base = pool_size :939; group bound
        // :929-932; slot range :981; load_kind scratch :982-987) that
        // never touches slot maps or residency masks. Sizing :159-162;
        // dispatch gate :843-844 + :1035-1036. Measured (docs
        // 164-166): hot-cache evictions 42 -> 0; miss-heavy
        // prefill-to-decode fixture 2.12-2.19x. Batch 94 / Research
        // 110 / Plan 058.
        KernelRule {
            rule_id: "scratch-bank-isolates-one-shot-operands-from-hot-cache".to_string(),
            gpu_concept: "ONE-SHOT operands (cold experts consumed once by a wide prefill group) must not share the resident bank with the recurring hot set: streaming cold groups through the hot bank EVICTS hot rows the next token needs and can evict a LATER cold group's operands before it runs -- bounded double-I/O churn (the source's own anti-shape comment: evaluate before the next group mutates dynamic bank slots). Reserve a SEPARATE fixed SCRATCH BANK at construction (bank = pool_size + scratch_slots; scratch sized to the worst one-shot group, floored at zero) and execute cold groups there: scratch rows bypass the hot cache's routing tables entirely (no slot-map or residency-mask mutation), so hot rows are STRUCTURALLY untouchable rather than carefully dodged. Overlap exactly one bounded group in flight (prefetch the next group while the current executes). Measured: hot-cache evictions 42 -> 0 and the miss-heavy prefill-to-decode fixture 2.12-2.19x faster. Regime: working set exceeding cache capacity; when every operand fits resident the scratch is dead weight (size 0) and dispatch stays on the resident path. Distinct from caller-owned-split-scratch (a HOST scratch carved per call into intermediate + output; this is a PERSISTENT DEVICE bank partition by operand LIFETIME), from superset-sized-scratch-across-variants (sizing one scratch to the worst variant of a shape family; this partitions by recurrence class -- one-shot vs recurring), and from transient-spike-pins-persistent-scratch (a non-recurring spike pinning oversized scratch forever; here the scratch is sized to the recurring worst GROUP and reused by every group). Source: jundot/omlx PR #3260 pool.py:837-894 (anti-shape _forward_expert_major: cold groups chunked through the dynamic banks, :852-858, the evict-then-evaluate comment at :891), :896-1011 (scratch path: docstring at :902 -- execute one-shot cold experts without replacing hot-cache rows; scratch base = pool_size at :939; group bound :929-932; slot range :981; load_kind scratch :982-987), :159-162 (sizing), :843-844 + :1035-1036 (dispatch gate), docs/soft_reap.md:106-110 + 164-166. Batch 94 / Research 110 / Plan 058.".to_string(),
            ref_shape: "// cold groups stream through the hot bank: later tokens lose their experts\nfn forward_expert_major(pool: &mut Pool, route: &[Expert]) -> BankOut {\n    let cold: Vec<Expert> = route.iter().copied().collect();\n    for g in chunk(cold, pool.cache_slots) {\n        for e in &g {\n            pool.allocate_miss(*e); // evicts hot rows (or earlier cold rows)\n        }\n        pool.write_bank(&g);\n        pool.eval_and_run(&g);\n    }\n    // a later group's operands were evicted by an earlier one: re-read\n}\n\n".to_string(),
            opt_pattern: "// one-shot operands run in a reserved scratch region; hot rows untouchable\nstruct Bank {\n    hot: Slots,\n    scratch: Slots, // bank = pool_size + scratch_slots, fixed at build\n}\nfn forward_expert_major_scratch(bank: &mut Bank, pinned: &[Expert],\n                                route: &[Expert]) -> BankOut {\n    let cold: Vec<Expert> = route.iter()\n        .filter(|e| !pinned.contains(e))\n        .copied()\n        .collect();\n    for g in chunk(cold, bank.scratch.len()) {\n        let base = bank.scratch.base(); // fixed region; NO slot-map mutation\n        bank.load_scratch_rows(&g, base); // hot rows structurally untouched\n        bank.run_group(&g, base);\n        bank.prefetch_next_group(); // one bounded group in flight\n    }\n    bank.run_resident(pinned)\n}\n\n".to_string(),
        },

        // -- sort-consumer-routes-by-physical-slot --
        // distilled from pool.py:_sort_group_for_qmm (:718-727;
        // threshold test at :722 -- slots.size < 64 skips the sort),
        // the gate + counters in _forward_resident_set (:819-822),
        // sorted_qmm_calls (:679), and the vendor gather-sort helpers
        // imported from mlx_lm.models.switch_layers (:15). Doc:
        // restores MLX's standard sorted gather-QMM path when manifest
        // order and cache placement differ from logical ids; bit-identical
        // output; +26.6% at 1024x256 (docs/soft_reap.md:117-121, 166-169).
        // Batch 94 / Research 110 / Plan 058.
        KernelRule {
            rule_id: "sort-consumer-routes-by-physical-slot".to_string(),
            gpu_concept: "When a remapping layer (logical expert id to physical bank slot) sits between routing and a vendor gather kernel whose fast path assumes ASCENDING gather indices, sort the consumer's routes by physical slot before the gather and un-permute the outputs after: argsort the slot vector, gather sorted, inverse-scatter each row back to its route position. Output is BIT-IDENTICAL (a pure permutation of gather rows with order restored exactly), and the vendor's sorted-gather fast path is restored -- measured +26.6% prefill at 1024x256. Gate the sort on an AMORTIZATION THRESHOLD (64 routed rows in the source): below it the argsort costs more than the unsorted-gather penalty and must not run. Physical order is an API CONTRACT with the gather kernel -- document it at the dispatch site and keep counters (sorted groups, sorted routes, sorted QMM calls) so the fast path's activation is observable in stats rather than folklore. Distinct from host-scratch-mirrors-slot-order-for-coalesced-writes (the HOST write-side of slot-order locality -- carve scratch in slot order so batched writes coalesce; this is the DEVICE read/gather side -- consumer route ordering feeding a vendor kernel's contract), from order-stable-topk-via-index-sort (sort-index-truncate-resort for stable top-k retention; here argsort exists to satisfy a downstream kernel's fast path, not retention stability), and from l2-grouped-tile-schedule (scheduling WORKGROUPS by cache locality; this orders the DATA indices of one dispatch). Source: jundot/omlx PR #3260 pool.py:718-727 (_sort_group_for_qmm: threshold test at :722, argsort + inverse permutation), :819-822 (gate + sorted group/route counters), :679 (sorted_qmm_calls), :15 (gather-sort helpers imported from the vendor's switch_layers), docs/soft_reap.md:117-121 + 166-169 (bit-identical, +26.6%). Batch 94 / Research 110 / Plan 058.".to_string(),
            ref_shape: "// routes in logical-expert order into a gather that prefers sorted indices\nfn qmm_unsorted(bank: &Bank, route: &[Expert]) -> Rows {\n    let slots: Vec<usize> = route.iter().map(|e| bank.slot_of(*e)).collect();\n    // the remap scrambled physical order: the vendor's sorted-gather path\n    // does not recognize the access pattern -- slow unsorted gather\n    bank.gather_qmm(&slots)\n}\n\n".to_string(),
            opt_pattern: "// threshold-gated argsort: physical order restored, outputs un-permuted\nconst SORT_MIN_ROWS: usize = 64;\nfn qmm_sorted(bank: &Bank, route: &[Expert], out: &mut Rows) -> bool {\n    let slots: Vec<usize> = route.iter().map(|e| bank.slot_of(*e)).collect();\n    if route.len() < SORT_MIN_ROWS {\n        *out = bank.gather_qmm(&slots); // sort costs more than it saves\n        return false;\n    }\n    let mut order: Vec<usize> = (0..slots.len()).collect();\n    order.sort_by_key(|i| slots[*i]); // ascending physical slot order\n    let sorted: Vec<usize> = order.iter().map(|i| slots[*i]).collect();\n    let gathered = bank.gather_qmm(&sorted); // vendor fast path recognized\n    for (dst, src) in order.iter().enumerate() {\n        out[*src] = gathered[dst]; // inverse scatter: bit-identical output\n    }\n    true // counter: one more sorted group (activation observable)\n}\n\n".to_string(),
        },

        // -- row-addressable-operand-index-not-full-tensor-map --
        // distilled from safetensors.py: header-only expert index
        // (docstring :66 -- index stacked switch_mlp tensors WITHOUT
        // mapping their payloads; header cache :91-95; data start
        // :141; w1/w2/w3 aliases :116-118; stacked fused halves
        // :242-254; fragmented row_sources :274-329 with the exact-
        // byte guard :315-320). THE HAZARD: the legacy path guards
        // uneven division (:403-404) but the schema path floor-
        // divides UNGUARDED (:269) -- every addressed read after row
        // 0 drifts into the previous row's tail (offset math :626):
        // silent weight corruption. Batch 94 / Research 110 /
        // Plan 058.
        KernelRule {
            rule_id: "row-addressable-operand-index-not-full-tensor-map".to_string(),
            gpu_concept: "When operands are addressable at ROW granularity (per-expert weight/scale/bias rows inside sharded quantized tensors), consume them through a header-only ROW-ADDRESS index -- read each file's 8-byte header length and JSON header once, cache it per filename, derive every row's absolute offset as data-base + header offset + row times row-bytes -- and read ONLY the addressed rows: no payload mmap, no whole-shard staging, host working set is the tiny index rather than the tensor. Support both layouts from one index: STACKED (all experts contiguous; row stride = data_bytes / num_experts under an EVEN-DIVISION guard) and FRAGMENTED (each row sourced from its own shard via a per-row source tuple with an exact-byte guard). THE HAZARD TWIN is the unguarded stride derivation: the legacy path raises on uneven division while the schema path floor-divides silently -- and every subsequent row-addressed read drifts into the previous row's tail with no exception: silent weight corruption on any tensor with padding or non-contiguous storage. The same contract appears a third time as the fragmented path's exact-byte check -- the guard must exist in EVERY constructor of the stride, not one (the merkle_root lesson class: one constructor guarded, its twin not). Distinct from kv-window-device-resident-ring-append (the DEVICE axis -- append the new KV row rather than re-upload a snapshot; this is the STORAGE axis -- address only the rows a route needs), from assigned-columns-only-staging-dequant (DEVICE column slicing before dequant; STORAGE row addressing before read), and from block-contiguous-weight-layout (device-side layout chosen for coalesced reads; here the disk layout is fixed and the INDEX is what avoids paying for it wholesale). Source: jundot/omlx PR #3260 safetensors.py:66 (index without mapping payloads), :91-95 (header cache per filename), :141 (data start from 8 + header_size + offset), :116-118 (w1/w2/w3 aliases), :242-254 (stacked fused halves), :274-329 (fragmented row_sources), :315-320 (exact-byte guard), :403-404 + :411 (legacy GUARDED division), :269 (schema path UNGUARDED data_bytes // num_experts), :626 (row offset math). Batch 94 / Research 110 / Plan 058.".to_string(),
            ref_shape: "// whole-shard staging + unguarded stride: silent row drift\nfn read_expert(shard: &Mmap, expert: usize, hdr: &Header) -> Vec<u8> {\n    let row_bytes = hdr.data_bytes / hdr.num_experts; // silent floor: padding\n    // makes row_bytes too small -- expert N reads row N-1's tail\n    let off = hdr.data_start + expert * row_bytes;\n    shard[off..off + row_bytes].to_vec()\n}\n\n".to_string(),
            opt_pattern: "// header-only index: addressed rows cross the bus; guarded stride\nstruct RowIndex {\n    headers: HashMap<String, (u64, Header)>, // (data base, header) per file\n}\nimpl RowIndex {\n    fn row_location(&self, file: &str, expert: usize) -> RowSource {\n        let (base, hdr) = self.header(file);\n        match hdr.layout {\n            Layout::Stacked => {\n                assert!(hdr.data_bytes % hdr.num_experts == 0); // GUARDED\n                let stride = hdr.data_bytes / hdr.num_experts;\n                RowSource::Span { file, start: base + expert * stride, len: stride }\n            }\n            Layout::Fragmented => {\n                let src = hdr.row_sources[expert].clone(); // per-row shard\n                debug_assert!(src.len == hdr.row_bytes); // exact-byte guard\n                src\n            }\n        }\n    }\n    fn read_rows(&self, route: &[usize]) -> Vec<Row> {\n        route.iter().map(|e| self.pread_row(*e)).collect() // addressed only\n    }\n}\n\n".to_string(),
        },

    ]
}
